#include "stdlib/stats/base/dists/gamma/entropy.h"
#include "stdlib/math/base/special/ln.h"
#include "stdlib/math/base/special/gammaln.h"
#include "stdlib/math/base/special/digamma.h"

/**
* Evaluates the differential entropy for a gamma distribution with shape parameter `alpha` and rate parameter `beta`.
*
* @param alpha    Shape parameter
* @param beta     Rate parameter
* @returns        Entropy
*
* @example
* double y = stdlib_base_dists_gamma_entropy( 1.0, 1.0 );
* // returns ~1.0
*
* @example
* double y = stdlib_base_dists_gamma_entropy( 4.0, 12.0 );
* // returns ~-0.462
*
* @example
* double y = stdlib_base_dists_gamma_entropy( 8.0, 2.0 );
* // returns ~1.723
*
* @example
* double y = stdlib_base_dists_gamma_entropy( 1.0, -0.1 );
* // returns NaN
*
* @example
* double y = stdlib_base_dists_gamma_entropy( -0.1, 1.0 );
* // returns NaN
*
* @example
* double y = stdlib_base_dists_gamma_entropy( 2.0, NaN );
* // returns NaN
*
* @example
* double y = stdlib_base_dists_gamma_entropy( NaN, 2.0 );
* // returns NaN
*/
double stdlib_base_dists_gamma_entropy( const double alpha, const double beta ) {
	double out;
	if ( alpha <= 0.0 || beta <= 0.0 ) {
		return 0.0 / 0.0;
	}
	out = alpha - stdlib_base_ln( beta );
	out += stdlib_base_gammaln( alpha );
	out += ( 1.0-alpha ) * stdlib_base_digamma( alpha );
	return out;
}
